def insert(self, key, val):
        update = [None] * (self.max_level + 1)
        cur = self.head
        for i in range(self.level, -1, -1):
            while cur.forward[i] and cur.forward[i].key < key:
                cur = cur.forward[i]
            update[i] = cur
        nxt = cur.forward[0]
        if nxt and nxt.key == key:
            nxt.val = val  # Update in-place without allocating duplicate node
            return
        new_lvl = self._random_level()
        if new_lvl > self.level:
            for i in range(self.level + 1, new_lvl + 1):
                update[i] = self.head
            self.level = new_lvl
        node = SkipNode(key, val, new_lvl)
        for i in range(new_lvl + 1):
            node.forward[i] = update[i].forward[i]
            update[i].forward[i] = node
